  "isabelle|class|1": {"name": "命知らずの荒くれ者", "info": "[ガードカウンター]範囲内の敵を攻撃し、挑発を与え、追加でダメージ減少効果を与える。", "detail": "[ガードカウンター]\n発動条件：ガード後、射程内にターゲットがいる場合に発動\n円形の範囲内の敵に<color=#C8B450>{DAMAGE:damageAdjust_ex+230}%</color>のダメージと挑発を与え、範囲内の敵が与えるダメージを<color=#C8B450>12%</color>ダウンさせる（<color=#C8B450>6</color>秒持続）。"},
  "isabelle|auto|0": {"name": "王と相まみえず", "info": "自分に追加でダメージ軽減効果を与える。", "detail": "自分に追加ダメージ軽減<color=#C8B450>{BUFF:buffEffectAdjust+30}%</color>の効果を与える（<color=#C8B450>6</color>秒持続）。"},
  "isabelle|extreme|0": {"name": "果てなき根絶やし", "info": "自分に防御力アップを与えて指定の地点に移動し、その後範囲内の敵を攻撃して、挑発とアンバランスを与える。", "detail": "自分に防御力<color=#C8B450>{BUFF:buffEffectAdjust+30}%</color>の効果を与え（<color=#C8B450>12</color>秒持続）、指定の地点に移動する。円形の範囲内の敵に<color=#C8B450>{DAMAGE:damageAdjust+300}%</color>のダメージと<color=#C8B450>4</color>のアンバランスを与え、挑発を与える。その後、円形の範囲内の敵に<color=#C8B450>{DAMAGE:damageAdjust2+650}%</color>のダメージと<color=#C8B450>4</color>のアンバランスを与え、挑発を与える。"},
