  "tomoe|passive|0": {"name": "春桜返し", "info": "必殺技を使用するたびに、自分のクラススキルのクールダウンがゼロになる。", "detail": "必殺技を使用するたびに、自分のクラススキルのクールダウンがゼロになる。"},
  "yuhong|normal|0": {"name": "ファイアリングピン", "info": "敵に1段攻撃をする。", "detail": "1段：敵1体に<color=#C8B450>{DAMAGE:damageAdjust+195}%</color>のダメージを与える。"},
