  "patra|class|0": {"name": "亡骸の戴冠", "info": "[チャージ]自分の必殺技チャージを増加させる。", "detail": "[チャージ]\n自分の必殺技チャージを<color=#C8B450>{COST:costAdjust+30000}</color>増加させる。"},
